-- Integration tokens for the settings integrations page (#287, part of #25):
--   * workspace_integration: one row per (workspace, kind), kind email_intake (the private intake
--     address) or ics_feed (the private ICS feed URL). token_hash is the sha256 hex of the token,
--     unique across workspaces; the token itself is never stored and is shown once. Rotating
--     replaces the hash, so the old token stops working at once. Tenant table under FORCE RLS
--     (tenantPolicy()). The intake and feed behaviour is the Capture milestone (#54, #53).
-- New table and policy only: nothing existing is altered or dropped.
CREATE TABLE "workspace_integration" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"kind" text NOT NULL,
	"token_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"rotated_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "workspace_integration_workspace_kind_uq" UNIQUE("workspace_id","kind"),
	CONSTRAINT "workspace_integration_token_hash_uq" UNIQUE("token_hash"),
	CONSTRAINT "workspace_integration_kind_chk" CHECK (kind in ('email_intake', 'ics_feed'))
);
